/* DAILY COUNTER - count something toward a daily goal (water, pages, push-ups, breaks). p0pc0rn example skeleton (p0pc0rn Kit).
   Slots come from window.SLOTS (the host writes them); every slot has a default, so the app also runs with no slots at all.
   Host features (window.p0) are optional: without them the app still works (it just skips posting to the chat). */

// ===== SLOTS =====
const SL = window.SLOTS || {};
const TITLE = String(SL.title || 'Water').slice(0, 22);
const ACCENT = /^#[0-9a-fA-F]{6}$/.test(SL.accent || '') ? SL.accent : '#32ade6';
const GOAL = Math.max(1, Math.min(100, Math.round(+SL.goal || 8)));
const STEP = Math.max(1, Math.min(GOAL, Math.round(+SL.step || 1)));
const UNIT = String(SL.unit || 'glasses').slice(0, 14);
const ICON = typeof SL.icon === 'string' && SL.icon ? SL.icon : 'drop';
const CHEERS = Array.isArray(SL.cheers) && SL.cheers.length ? SL.cheers.slice(0, 5).map((s) => String(s).slice(0, 40)) : ['Nice!', 'Keep going', 'Halfway there', 'Almost!'];
const DONE_TEXT = String(SL.done_text || 'Goal reached for today').slice(0, 40);

// ===== STATE (per day, saved) =====
const dayKey = () => new Date().toISOString().slice(0, 10);
let st = { day: dayKey(), count: 0, history: [] };   // history = the last 7 finished days' counts

function setup() {
  K.setup({ mode: 'light', accent: ACCENT });
  const saved = K.load('counter.v1', null);
  if (saved && saved.day) st = saved;
  rollover();
  K.scene('main', drawMain);
}

function rollover() {
  if (st.day === dayKey()) return;
  st.history = st.history.concat([st.count]).slice(-7);
  st.day = dayKey(); st.count = 0; K.save('counter.v1', st);
}

function add(n) {
  const before = st.count;
  st.count = Math.max(0, st.count + n);
  K.save('counter.v1', st);
  if (n > 0) {
    K.sfx(st.count >= GOAL && before < GOAL ? 'win' : 'pop');
    if (st.count >= GOAL && before < GOAL) {
      K.burst(K.W / 2, K.H * 0.36, { n: 40, colors: [ACCENT, K.C.good], shape: 'confetti' });
      if (window.p0 && window.p0.chat) window.p0.chat.post({ title: TITLE, severity: 'info', text: DONE_TEXT + ' (' + st.count + ' ' + UNIT + ').' });
    } else K.toast(CHEERS[st.count % CHEERS.length], { tone: 'good', icon: ICON, ms: 1200 });
  }
}

function drawMain() {
  K.backdrop({ top: K.C.bg, bottom: K.lighten(ACCENT, 0.85) });
  K.navBar(TITLE, 0, { sub: K.fmt.date(Date.now()) });
  const cx = K.W / 2, cy = K.H * 0.36, r = Math.min(K.W * 0.32, 130);
  const t = Math.min(1, K.count('ring', st.count, 500) / GOAL);
  K.progressRing(cx, cy, r, t, { width: 18, color: [ACCENT, K.lighten(ACCENT, 0.3)], glow: st.count >= GOAL });
  K.icon(ICON, cx, cy - 34, 34, ACCENT, { fill: true });
  K.num(String(st.count), cx, cy + 18, 'display', K.C.text, { align: 'center' });
  K.text('of ' + GOAL + ' ' + UNIT, cx, cy + 46, 'subhead', K.C.text2, { align: 'center' });
  const bw = K.W - 2 * K.S.l, by = cy + r + 40;
  if (K.button('add', K.S.l, by, bw, 56, '+' + STEP + ' ' + UNIT, { style: 'primary', icon: 'plus', alpha: K.stagger(1) })) add(STEP);
  if (K.button('undo', K.S.l, by + 68, bw, 48, 'Undo', { style: 'secondary', icon: 'undo', alpha: K.stagger(2), disabled: st.count === 0 })) add(-STEP);
  const hist = st.history.length ? st.history : [0];
  K.text('LAST 7 DAYS', K.S.l, by + 150, 'label', K.C.text2);
  K.bars(hist.concat([st.count]), K.S.l, by + 162, bw, 80, { color: ACCENT, highlight: hist.length, max: Math.max(GOAL, ...hist, st.count), gap: 8, r: 4 });
}

function draw() { rollover(); K.render(); }
